    return f'{v:.2f}'


def tokens(expr, letras=''):
    lista = [None] * len(expr)
    n = 0
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit():
            num = ''
            while i < len(expr) and expr[i].isdigit():
                num = num + expr[i]
                i = i + 1
            lista[n] = num
            n = n + 1
            continue
        if c in '+-*/^()' or c in letras:
            lista[n] = c
            n = n + 1
        elif c != ' ':
            raise ValueError(f'carácter {c}')
        i = i + 1
    return lista[:n]


